"use client";

import * as React from "react";

import {
  type CardResult,
  type CvvResult,
  type ExpiryResult,
  formatCardNumber,
  formatExpiry,
  validateCardNumber,
  validateCvv,
  validateExpiry,
} from "../../lib/card";
import { cn, controlClasses, Field, FieldBadge, useFieldState } from "./field";

type Base = Omit<
  React.ComponentProps<"input">,
  "value" | "defaultValue" | "onChange" | "type"
>;

interface Common {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  validateOn?: "blur" | "change";
  label?: string;
  description?: string;
  containerClassName?: string;
}

/* ── Card number ─────────────────────────────────────────────────────────── */

export interface CardNumberInputProps extends Base, Common {
  onValidationChange?: (result: CardResult) => void;
  /** Name the detected network. Default `true`. */
  showNetwork?: boolean;
}

export function CardNumberInput({
  value: controlledValue,
  defaultValue = "",
  onValueChange,
  onValidationChange,
  validateOn = "blur",
  showNetwork = true,
  label,
  description,
  className,
  containerClassName,
  id,
  onBlur,
  ...props
}: CardNumberInputProps) {
  const reactId = React.useId();
  const inputId = id ?? `card-${reactId}`;
  const messageId = `${inputId}-message`;

  const field = useFieldState<CardResult>({
    value: controlledValue,
    defaultValue,
    onValueChange,
    onValidationChange,
    validate: validateCardNumber,
    // Regroups live, and the grouping itself changes with the network (Amex
    // is 4-6-5, everyone else 4-4-4-4).
    transform: formatCardNumber,
    validateOn,
  });

  const network = showNetwork ? field.result.network : undefined;

  return (
    <Field
      id={inputId}
      messageId={messageId}
      label={label}
      message={field.error ?? description}
      tone={field.error ? "error" : "muted"}
      className={containerClassName}
    >
      <div className="relative">
        <input
          {...props}
          id={inputId}
          type="text"
          inputMode="numeric"
          autoComplete="cc-number"
          placeholder={props.placeholder ?? "6521 1234 5678 9012"}
          value={field.value}
          onChange={(event) => field.setValue(event.target.value)}
          onBlur={(event) => {
            field.markTouched();
            onBlur?.(event);
          }}
          aria-invalid={Boolean(field.error)}
          aria-describedby={messageId}
          className={cn(
            controlClasses({
              error: Boolean(field.error),
              success: field.success,
            }),
            "tracking-[0.1em]",
            network && "pr-36",
            className,
          )}
        />
        {network && field.result.valid && <FieldBadge>{network}</FieldBadge>}
      </div>
    </Field>
  );
}

/* ── Expiry ──────────────────────────────────────────────────────────────── */

export interface CardExpiryInputProps extends Base, Common {
  onValidationChange?: (result: ExpiryResult) => void;
}

export function CardExpiryInput({
  value: controlledValue,
  defaultValue = "",
  onValueChange,
  onValidationChange,
  validateOn = "blur",
  label,
  description,
  className,
  containerClassName,
  id,
  onBlur,
  ...props
}: CardExpiryInputProps) {
  const reactId = React.useId();
  const inputId = id ?? `expiry-${reactId}`;
  const messageId = `${inputId}-message`;

  const validate = React.useCallback((raw: string) => validateExpiry(raw), []);

  const field = useFieldState<ExpiryResult>({
    value: controlledValue,
    defaultValue,
    onValueChange,
    onValidationChange,
    validate,
    transform: formatExpiry,
    validateOn,
  });

  return (
    <Field
      id={inputId}
      messageId={messageId}
      label={label}
      message={field.error ?? description}
      tone={field.error ? "error" : "muted"}
      className={containerClassName}
    >
      <input
        {...props}
        id={inputId}
        type="text"
        inputMode="numeric"
        autoComplete="cc-exp"
        placeholder={props.placeholder ?? "MM/YY"}
        value={field.value}
        onChange={(event) => field.setValue(event.target.value)}
        onBlur={(event) => {
          field.markTouched();
          onBlur?.(event);
        }}
        aria-invalid={Boolean(field.error)}
        aria-describedby={messageId}
        className={cn(
          controlClasses({
            error: Boolean(field.error),
            success: field.success,
          }),
          "tracking-[0.16em]",
          className,
        )}
      />
    </Field>
  );
}

/* ── CVV ─────────────────────────────────────────────────────────────────── */

export interface CVVInputProps extends Base, Common {
  onValidationChange?: (result: CvvResult) => void;
  /**
   * Expected length — pass `cvvLength` from the card number's result so Amex
   * correctly asks for four digits.
   */
  length?: number;
}

export function CVVInput({
  value: controlledValue,
  defaultValue = "",
  onValueChange,
  onValidationChange,
  validateOn = "blur",
  length = 3,
  label,
  description,
  className,
  containerClassName,
  id,
  onBlur,
  ...props
}: CVVInputProps) {
  const reactId = React.useId();
  const inputId = id ?? `cvv-${reactId}`;
  const messageId = `${inputId}-message`;

  const validate = React.useCallback(
    (raw: string) => validateCvv(raw, length),
    [length],
  );

  const field = useFieldState<CvvResult>({
    value: controlledValue,
    defaultValue,
    onValueChange,
    onValidationChange,
    validate,
    transform: (raw) => raw.replace(/\D/g, "").slice(0, length),
    validateOn,
  });

  return (
    <Field
      id={inputId}
      messageId={messageId}
      label={label}
      message={field.error ?? description}
      tone={field.error ? "error" : "muted"}
      className={containerClassName}
    >
      <input
        {...props}
        id={inputId}
        // `password` so a CVV never lands in a screenshot or screen share.
        type="password"
        inputMode="numeric"
        autoComplete="cc-csc"
        placeholder={props.placeholder ?? "•".repeat(length)}
        value={field.value}
        onChange={(event) => field.setValue(event.target.value)}
        onBlur={(event) => {
          field.markTouched();
          onBlur?.(event);
        }}
        aria-invalid={Boolean(field.error)}
        aria-describedby={messageId}
        className={cn(
          controlClasses({
            error: Boolean(field.error),
            success: field.success,
          }),
          "tracking-[0.3em]",
          className,
        )}
      />
    </Field>
  );
}

"use client";

import { type ClassValue, clsx } from "clsx";
import { CircleAlert, Info } from "lucide-react";
import * as React from "react";
import { twMerge } from "tailwind-merge";

/**
 * Shared by every bharat-ui field. Defined here rather than imported from a
 * project's `@/lib/utils` so that installing a component can never overwrite
 * the consumer's own utils file.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export type FieldTone = "error" | "hint" | "muted";

export interface FieldProps {
  id: string;
  /** Id of the element holding the message; wire this into aria-describedby. */
  messageId: string;
  label?: string;
  /** Resolved message text — an error, a warning, or the fallback description. */
  message?: string;
  tone?: FieldTone;
  className?: string;
  children: React.ReactNode;
}

/** Label + control + message, with the aria plumbing already correct. */
export function Field({
  id,
  messageId,
  label,
  message,
  tone = "muted",
  className,
  children,
}: FieldProps) {
  return (
    <div className={cn("w-full", className)}>
      {label && (
        <label htmlFor={id} className="mb-1.5 block text-sm font-medium">
          {label}
        </label>
      )}

      {children}

      {message && (
        <p
          id={messageId}
          // Only errors interrupt a screen reader; hints are read on focus.
          role={tone === "error" ? "alert" : undefined}
          className={cn(
            "mt-1.5 flex items-start gap-1.5 text-xs",
            tone === "error"
              ? "text-red-600 dark:text-red-400"
              : "text-neutral-500 dark:text-neutral-400",
          )}
        >
          {tone === "error" ? (
            <CircleAlert className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : tone === "hint" ? (
            <Info className="mt-px size-3.5 shrink-0" aria-hidden />
          ) : null}
          {message}
        </p>
      )}
    </div>
  );
}

/** Border/ring classes shared by every text control, keyed on validity. */
export function controlClasses(state: {
  error?: boolean;
  success?: boolean;
}): string {
  return cn(
    "h-10 w-full rounded-lg border bg-transparent px-3 py-2 font-mono text-sm outline-none transition",
    "placeholder:font-sans placeholder:text-neutral-400 dark:placeholder:text-neutral-600",
    "disabled:cursor-not-allowed disabled:opacity-50",
    "focus-visible:ring-[3px]",
    state.error
      ? "border-red-500 focus-visible:ring-red-500/20"
      : state.success
        ? "border-emerald-500 focus-visible:ring-emerald-500/20"
        : "border-neutral-300 focus-visible:border-neutral-900 focus-visible:ring-neutral-900/10 dark:border-neutral-700 dark:focus-visible:border-neutral-300 dark:focus-visible:ring-neutral-100/10",
  );
}

export interface ValidationLike {
  valid: boolean;
  error?: { message: string };
}

/**
 * The controlled/uncontrolled + touched + report-upward logic every field here
 * needs. Kept in one place so all of them behave identically: errors appear on
 * blur by default, then update live once the user has been warned.
 */
export function useFieldState<T extends ValidationLike>(options: {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  onValidationChange?: (result: T) => void;
  validate: (raw: string) => T;
  /** Optional input mask applied on every keystroke. */
  transform?: (raw: string) => string;
  validateOn?: "blur" | "change";
}) {
  const {
    value: controlled,
    defaultValue = "",
    onValueChange,
    onValidationChange,
    validate,
    transform,
    validateOn = "blur",
  } = options;

  const isControlled = controlled !== undefined;
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue);
  const value = isControlled ? controlled : uncontrolled;
  const [touched, setTouched] = React.useState(false);

  const result = React.useMemo(() => validate(value), [value, validate]);

  // Report upward only when the outcome actually changes, so consumers can put
  // setState directly in the callback without a render loop.
  const lastReported = React.useRef<string>("");
  React.useEffect(() => {
    const key = JSON.stringify(result);
    if (key === lastReported.current) return;
    lastReported.current = key;
    onValidationChange?.(result);
  }, [result, onValidationChange]);

  const setValue = React.useCallback(
    (next: string) => {
      const masked = transform ? transform(next) : next;
      if (!isControlled) setUncontrolled(masked);
      onValueChange?.(masked);
    },
    [isControlled, onValueChange, transform],
  );

  const shouldValidate = validateOn === "change" || touched;
  const error =
    shouldValidate && value.trim() !== "" ? result.error?.message : undefined;

  return {
    value,
    setValue,
    result,
    touched,
    markTouched: () => setTouched(true),
    error,
    success: result.valid,
  };
}

/** Small right-aligned badge inside a control (bank name, entity type, …). */
export function FieldBadge({ children }: { children: React.ReactNode }) {
  return (
    <span className="pointer-events-none absolute right-2 top-1/2 flex max-w-[45%] -translate-y-1/2 items-center gap-1 truncate rounded-full bg-emerald-500/10 px-2 py-0.5 text-xs font-medium text-emerald-700 dark:text-emerald-400">
      {children}
    </span>
  );
}

/**
 * Payment card validation, with RuPay support.
 *
 * Most card libraries were written for Visa/Mastercard/Amex and silently reject
 * RuPay, which is the majority of debit cards issued in India. The BIN ranges
 * below cover it properly.
 *
 * ⚠️ Never send a raw PAN to your own server unless you are PCI-DSS compliant.
 * Use your gateway's tokenisation (Razorpay, Juspay, Stripe) and treat this as
 * a typo-catcher only.
 */

export type CardNetwork =
  | "RuPay"
  | "Visa"
  | "Mastercard"
  | "American Express"
  | "Diners Club"
  | "Maestro"
  | "Discover";

interface NetworkSpec {
  network: CardNetwork;
  test: (digits: string) => boolean;
  lengths: number[];
  /** Digit-group sizes for display. */
  gaps: number[];
  cvvLength: number;
}

const between = (value: string, lo: number, hi: number) => {
  const n = Number(value);
  return n >= lo && n <= hi;
};

const NETWORKS: readonly NetworkSpec[] = [
  {
    network: "American Express",
    test: (d) => /^3[47]/.test(d),
    lengths: [15],
    gaps: [4, 6, 5],
    cvvLength: 4,
  },
  {
    // Checked before Discover/Maestro: their ranges overlap at 6x, and in India
    // a 6xxx card is overwhelmingly more likely to be RuPay.
    network: "RuPay",
    test: (d) => /^(508[5-9]|60[6-9]|65[23]|81[7-9]|82[0-2])/.test(d),
    lengths: [16],
    gaps: [4, 4, 4, 4],
    cvvLength: 3,
  },
  {
    network: "Visa",
    test: (d) => /^4/.test(d),
    lengths: [13, 16, 19],
    gaps: [4, 4, 4, 4],
    cvvLength: 3,
  },
  {
    network: "Mastercard",
    test: (d) =>
      between(d.slice(0, 2), 51, 55) || between(d.slice(0, 4), 2221, 2720),
    lengths: [16],
    gaps: [4, 4, 4, 4],
    cvvLength: 3,
  },
  {
    network: "Diners Club",
    test: (d) => /^(36|38|30[0-5])/.test(d),
    lengths: [14, 16],
    gaps: [4, 6, 4],
    cvvLength: 3,
  },
  {
    network: "Discover",
    test: (d) => /^(6011|64[4-9]|65)/.test(d),
    lengths: [16, 19],
    gaps: [4, 4, 4, 4],
    cvvLength: 3,
  },
  {
    network: "Maestro",
    test: (d) => /^(5018|5020|5038|56|57|58|6304|6759|676[1-3])/.test(d),
    lengths: [12, 13, 14, 15, 16, 17, 18, 19],
    gaps: [4, 4, 4, 4],
    cvvLength: 3,
  },
];

/** Identify the network from as few as two digits. */
export function detectNetwork(input: string): NetworkSpec | undefined {
  const digits = input.replace(/\D/g, "");
  if (!digits) return undefined;
  return NETWORKS.find((spec) => spec.test(digits));
}

/** The Luhn (mod-10) check every card network uses. */
export function luhnValid(digits: string): boolean {
  if (!/^\d+$/.test(digits)) return false;
  let sum = 0;
  let double = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let value = Number(digits[i]);
    if (double) {
      value *= 2;
      if (value > 9) value -= 9;
    }
    sum += value;
    double = !double;
  }
  return sum % 10 === 0;
}

export type CardErrorCode =
  | "empty"
  | "not_digits"
  | "unknown_network"
  | "bad_length"
  | "bad_checksum";

export interface CardResult {
  valid: boolean;
  normalized: string;
  network?: CardNetwork;
  /** How many digits the CVV should be — 4 for Amex, 3 otherwise. */
  cvvLength?: number;
  formatted?: string;
  error?: { code: CardErrorCode; message: string };
}

function bad(
  code: CardErrorCode,
  message: string,
  normalized: string,
): CardResult {
  return { valid: false, normalized, error: { code, message } };
}

/** Group digits for display, using the network's own convention. */
export function formatCardNumber(input: string): string {
  const digits = input.replace(/\D/g, "").slice(0, 19);
  const gaps = detectNetwork(digits)?.gaps ?? [4, 4, 4, 4];

  const parts: string[] = [];
  let cursor = 0;
  for (const size of gaps) {
    if (cursor >= digits.length) break;
    parts.push(digits.slice(cursor, cursor + size));
    cursor += size;
  }
  if (cursor < digits.length) parts.push(digits.slice(cursor));
  return parts.join(" ");
}

export function validateCardNumber(input: string): CardResult {
  const digits = input.replace(/\D/g, "");

  if (!input.trim()) return bad("empty", "Enter a card number.", digits);
  if (/[^\d\s-]/.test(input)) {
    return bad("not_digits", "A card number is digits only.", digits);
  }

  const spec = detectNetwork(digits);
  if (!spec) {
    return bad(
      "unknown_network",
      "We don't recognise this card network.",
      digits,
    );
  }
  if (!spec.lengths.includes(digits.length)) {
    const expected = spec.lengths.join(" or ");
    return bad(
      "bad_length",
      `A ${spec.network} card is ${expected} digits — ${digits.length} so far.`,
      digits,
    );
  }
  if (!luhnValid(digits)) {
    return bad("bad_checksum", "That card number failed its checksum.", digits);
  }

  return {
    valid: true,
    normalized: digits,
    network: spec.network,
    cvvLength: spec.cvvLength,
    formatted: formatCardNumber(digits),
  };
}

/* ── Expiry ──────────────────────────────────────────────────────────────── */

export type ExpiryErrorCode = "empty" | "bad_shape" | "bad_month" | "expired";

export interface ExpiryResult {
  valid: boolean;
  normalized: string;
  month?: number;
  year?: number;
  error?: { code: ExpiryErrorCode; message: string };
}

/** Insert the slash as the user types: `1229` → `12/29`. */
export function formatExpiry(raw: string): string {
  const digits = raw.replace(/\D/g, "").slice(0, 4);
  // A lone 2–9 can only be a month if we pad it, e.g. "3" → "03/".
  if (digits.length === 1 && Number(digits) > 1) return `0${digits}/`;
  if (digits.length <= 2) return digits;
  return `${digits.slice(0, 2)}/${digits.slice(2)}`;
}

export function validateExpiry(
  input: string,
  asOf: Date = new Date(),
): ExpiryResult {
  const digits = input.replace(/\D/g, "");
  if (!input.trim()) {
    return {
      valid: false,
      normalized: digits,
      error: { code: "empty", message: "Enter the expiry date." },
    };
  }
  if (digits.length !== 4) {
    return {
      valid: false,
      normalized: digits,
      error: { code: "bad_shape", message: "Use MM/YY." },
    };
  }

  const month = Number(digits.slice(0, 2));
  const year = 2000 + Number(digits.slice(2));

  if (month < 1 || month > 12) {
    return {
      valid: false,
      normalized: digits,
      month,
      year,
      error: { code: "bad_month", message: "Month must be between 01 and 12." },
    };
  }

  // A card is valid through the *last day* of its expiry month.
  const expiresAfter = new Date(year, month, 0, 23, 59, 59);
  if (expiresAfter < asOf) {
    return {
      valid: false,
      normalized: digits,
      month,
      year,
      error: { code: "expired", message: "This card has expired." },
    };
  }

  return { valid: true, normalized: digits, month, year };
}

/* ── CVV ─────────────────────────────────────────────────────────────────── */

export type CvvErrorCode = "empty" | "not_digits" | "wrong_length";

export interface CvvResult {
  valid: boolean;
  normalized: string;
  error?: { code: CvvErrorCode; message: string };
}

export function validateCvv(input: string, expectedLength = 3): CvvResult {
  const digits = input.replace(/\D/g, "");
  if (!input.trim()) {
    return {
      valid: false,
      normalized: digits,
      error: { code: "empty", message: "Enter the CVV." },
    };
  }
  if (/[^\d\s]/.test(input)) {
    return {
      valid: false,
      normalized: digits,
      error: { code: "not_digits", message: "A CVV is digits only." },
    };
  }
  if (digits.length !== expectedLength) {
    return {
      valid: false,
      normalized: digits,
      error: {
        code: "wrong_length",
        message: `This card's CVV is ${expectedLength} digits.`,
      },
    };
  }
  return { valid: true, normalized: digits };
}
